/*! WordPress hooks */
(function() {
  window.wp = window.wp || {};
  var hooks = {};
  var actions = {};
  var filters = {};

  window.wp.hooks = {
    createHooks: function() { return window.wp.hooks; },
    addAction: function(name, namespace, callback, priority) {
      actions[name] = actions[name] || [];
      actions[name].push({ namespace: namespace, callback: callback, priority: priority || 10 });
      return window.wp.hooks;
    },
    addFilter: function(name, namespace, callback, priority) {
      filters[name] = filters[name] || [];
      filters[name].push({ namespace: namespace, callback: callback, priority: priority || 10 });
      return window.wp.hooks;
    },
    removeAction: function(name, namespace) {
      if (actions[name]) {
        actions[name] = actions[name].filter(function(a) { return a.namespace !== namespace; });
      }
      return window.wp.hooks;
    },
    removeFilter: function(name, namespace) {
      if (filters[name]) {
        filters[name] = filters[name].filter(function(f) { return f.namespace !== namespace; });
      }
      return window.wp.hooks;
    },
    hasAction: function(name) { return !!(actions[name] && actions[name].length); },
    hasFilter: function(name) { return !!(filters[name] && filters[name].length); },
    doAction: function(name) {
      var args = Array.prototype.slice.call(arguments, 1);
      if (actions[name]) {
        actions[name].forEach(function(action) {
          try { action.callback.apply(null, args); } catch(e) { console.warn(e); }
        });
      }
      return window.wp.hooks;
    },
    applyFilters: function(name, value) {
      var args = Array.prototype.slice.call(arguments, 1);
      var current = value;
      if (filters[name]) {
        filters[name].forEach(function(filter) {
          try {
            args[0] = current;
            current = filter.callback.apply(null, args);
          } catch(e) { console.warn(e); }
        });
      }
      return current;
    }
  };
})();
